from typing import List, Dict

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info
from taf.rfrl.procedures.resources.python.vm import get_file_size


def general_siso_auto_cloud_rf_scan(testing_env: TestingEnv, rf_scans_settings: List[Dict[str, str]]):
    """
    Based on:
    QC Test ID: 3366
    QC Test Name: [1.1] Manual_SiSo_TEST_RF_Sniffing_RF_Scanning_(3G_4G_5G)

    Should report to:
    QC Test ID: 45724
    QC Test Name: General_SiSo_Auto_Cloud_RF_scan

    :param testing_env: testing environment prepared for this test case
    :param rf_scans_settings: settings which should be used for RF Scans that will be run during this test;
                              each setting on the list will result in one RF Scan being run;
                              each setting consists of:
                              * rmod_name - required;
                              * antenna_name - optional (if None provided then antenna will not be set);
                              * cell_name - optional (if None provided then cell will not be set);
                              * capture_type - required, one of the following:
                                               'TX_COMBINED', 'TX_FEEDBACK', 'RX_COMBINED', 'RX_COMBINED_RAW', 'RX_CARRIER';
                              * antenna_panel - optional (if None provided then antenna panel will not be set), otherwise one of the following:
                                                'Full_Array', 'Top_Array', 'Bottom_Array', 'Left_Array', 'Right_Array', 'All_Arrays';
                              i.e.:
                              [{'rmod_name': 'RMOD-1',
                                'antenna_name': 'ANT-2',
                                'cell_name': 'NRCELL-1',
                                'capture_type': 'TX_COMBINED',
                                'antenna_panel': 'Full_Array'},
                               {'rmod_name': 'RMOD-3',
                                'antenna_name': None,
                                'cell_name': None,
                                'capture_type': 'RX_COMBINED_RAW',
                                'antenna_panel': None}]
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors
    download_dir_path = testing_env.downloads_dir_path
    act_rfi_testing_initial_state = {}
    testing_env.variables.set(name='act_rfi_testing_initial_state', value=act_rfi_testing_initial_state)

    for du in bts.dus:
        try:
            _store_initial_value_of_act_rfi_testing(act_rfi_testing_initial_state, du)
            _disable_act_rfi_testing(du)
            _run_rf_scan(du, rf_scans_settings[0], expect_rejection=True)
            _enable_act_rfi_testing(du)

            for rf_scan_settings in rf_scans_settings:
                try:
                    _run_rf_scan(du, rf_scan_settings)
                    result_file_path = _download_rf_scan_result_file(du, download_dir_path)
                    _validate_name_and_size_of_rf_scan_result_file(result_file_path)
                except ResultError as exc:
                    errors.add_from_exception(exc)

            _start_rf_scan_and_cancel_it(du, rf_scans_settings[0])
            _download_rf_scan_result_file(du, download_dir_path, expect_rejection=True)

        except ResultError as exc:
            errors.add_from_exception(exc)

    errors.check()


def teardown_for_general_siso_auto_cloud_rf_scan(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    act_rfi_testing_initial_state = testing_env.variables.get(name='act_rfi_testing_initial_state')

    for du in bts.dus:
        du.config.set(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                      param='actRfiTesting',
                      value=act_rfi_testing_initial_state[du.name])
        du.check_state(state='on_air')


def _store_initial_value_of_act_rfi_testing(act_rfi_testing_initial_state, du):
    act_rfi_testing_initial_state[du.name] = du.config.get(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                                                           param='actRfiTesting')


def _disable_act_rfi_testing(du):
    du.config.set(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                  param='actRfiTesting',
                  value='false')


def _enable_act_rfi_testing(du):
    du.config.set(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                  param='actRfiTesting',
                  value='true')


def _run_rf_scan(du, rf_scan_settings, expect_rejection=False):
    rmod = _get_rmod_from_rf_scan_settings(du, rf_scan_settings)
    antenna = _get_antenna_from_rf_scan_settings(rmod, rf_scan_settings)
    cell = _get_cell_from_rf_scan_settings(rmod, rf_scan_settings)
    du.rf_scan.run_rf_scan(rmod=rmod,
                           antenna=antenna,
                           cell=cell,
                           capture_type=rf_scan_settings['capture_type'],
                           antenna_panel=rf_scan_settings['antenna_panel'],
                           expect_rejection=expect_rejection)


def _start_rf_scan_and_cancel_it(du, rf_scan_settings):
    rmod = _get_rmod_from_rf_scan_settings(du, rf_scan_settings)
    antenna = _get_antenna_from_rf_scan_settings(rmod, rf_scan_settings)
    cell = _get_cell_from_rf_scan_settings(rmod, rf_scan_settings)
    du.rf_scan.run_rf_scan(rmod=rmod,
                           antenna=antenna,
                           cell=cell,
                           capture_type=rf_scan_settings['capture_type'],
                           antenna_panel=rf_scan_settings['antenna_panel'],
                           timeout=0)
    du.rf_scan.cancel_rf_scan()


def _get_rmod_from_rf_scan_settings(du, rf_scan_settings):
    for rmod in du.rmods:
        if rmod.name == rf_scan_settings['rmod_name']:
            return rmod


def _get_antenna_from_rf_scan_settings(rmod, rf_scan_settings):
    for antenna in rmod.antennas:
        if antenna.name == rf_scan_settings['antenna_name']:
            return antenna


def _get_cell_from_rf_scan_settings(rmod, rf_scan_settings):
    for cell in rmod.cells:
        if cell.name == rf_scan_settings['cell_name']:
            return cell


def _download_rf_scan_result_file(du, download_dir_path, expect_rejection=False):
    return du.rf_scan.download_rf_scan_result_file(download_dir_path=download_dir_path,
                                                   expect_rejection=expect_rejection)


@pretty_log
def _validate_name_and_size_of_rf_scan_result_file(result_file_path):
    log_info(f'Validating name and size of RF Scan result file {result_file_path}', to_console=True)
    _validate_name_of_rf_scan_result_file(result_file_path)
    _validate_size_of_rf_scan_result_file(result_file_path)
    log_info('Validation of RF Scan result file was successful', to_console=True)


def _validate_name_of_rf_scan_result_file(result_file_path):
    result_file_name = result_file_path.split('/')[-1]

    if not result_file_name.startswith('RFMonitoring_') or not result_file_name.endswith('.zip'):
        raise ResultError(f'RF Scan result file {result_file_path} name does not follow "RFMonitoring_*.zip" pattern')


def _validate_size_of_rf_scan_result_file(result_file_path):
    result_file_size = get_file_size(file_path=result_file_path)

    if result_file_size <= 0:
        raise ResultError(f'RF Scan result file {result_file_path} size {result_file_size} bytes is not bigger than 0 bytes')
